/* Independent native GUI software installer; unrelated to BIOS disk setup. */
#include "package.h"
static u8 bytes[MAX_FILE];
static UiScene scene;
static int window,page,field,quiet,optional=1,result;
static char package_path[128]="/boot/hello.sxp",root[128],status[80];
static Package *package=(Package *)bytes;
static char operation[32];
static int progress_done,progress_total;
static void draw(void){ui_begin(&scene);ui_fill(&scene,1,30,178,419,0xdce5f0);ui_text(&scene,18,55,"SINO 软件安装");const char *steps[]={"欢迎","许可协议","安装位置","组件选择","安装进度","完成"};for(int i=0;i<6;i++)ui_text(&scene,20,106+i*40,steps[i]);ui_fill(&scene,181,30,518,419,0xfafbfcu);
 if(operation[0]){ui_text(&scene,205,65,"卸载原生应用");ui_text(&scene,205,112,operation);ui_text(&scene,205,160,"将删除程序文件和注册信息。");ui_text(&scene,205,192,"安装目录中的用户文件会保留。");ui_text(&scene,205,256,status);ui_button(&scene,414,392,120,result==1?"完成":"确认卸载");}
 else{ui_text(&scene,205,65,steps[page]);if(page==0){ui_text(&scene,205,110,"欢迎安装本系统的原生应用包。");ui_text(&scene,205,150,"应用包路径（点击后可编辑）：");ui_fill(&scene,202,180,469,32,field==1?0xe4efff:0xffffff);ui_text(&scene,209,185,package_path);ui_text(&scene,205,242,"安装器独立运行在用户态。");ui_text(&scene,205,278,"不会执行包内的安装脚本或下载程序。");}
 if(page==1){ui_text(&scene,205,110,package->name);ui_text(&scene,205,154,package->license);ui_text(&scene,205,240,"继续即表示接受上述许可。");}
 if(page==2){ui_text(&scene,205,110,"程序安装目录（点击后可编辑）：");ui_fill(&scene,202,150,469,32,field==2?0xe4efff:0xffffff);ui_text(&scene,209,155,root);ui_text(&scene,205,222,"允许 /home/user/Programs/ 下的独立目录。");ui_text(&scene,205,258,"系统目录受保护，已占用文件不会被接管。");}
 if(page==3){ui_text(&scene,205,112,"[必选] 原生应用与运行文件");if(package->components&2)ui_button(&scene,205,165,350,optional?"[x] 可选文档和示例":"[ ] 可选文档和示例");else ui_text(&scene,205,170,"此应用包没有可选组件。");ui_text(&scene,205,244,"将创建桌面 / 应用菜单快捷方式。");ui_text(&scene,205,280,"失败时恢复文件、配置和快捷方式。");}
 if(page==4){ui_text(&scene,205,120,"正在复制和登记，请稍候……");ui_text(&scene,205,178,status);ui_fill(&scene,205,230,440,14,0xe0e3e8);if(progress_total)ui_fill(&scene,205,230,440*progress_done/progress_total,14,0x557da8);}
 if(page==5){ui_text(&scene,205,116,result==0?"应用已安装，可以从桌面启动。":"安装失败，详情见安装日志。");ui_text(&scene,205,160,status);ui_text(&scene,205,220,"F9 打开应用管理器，可修复或卸载。");ui_text(&scene,205,260,"日志：个人磁盘/.sino/install.log");}
 if(page!=4){ui_text(&scene,205,342,status);if(page>0&&page<4)ui_button(&scene,335,392,100,"上一步");ui_button(&scene,448,392,110,page==5?"完成":page==3?"开始安装":"下一步");}}
 if(page!=4)ui_button(&scene,575,392,100,"关闭");Scene(window,&scene);}
static void progress(u32 done,u32 total){progress_done=(int)done;progress_total=(int)total;copy(status,"已复制文件 ");number(done,status+strlen(status));copy(status+strlen(status)," / ");number(total,status+strlen(status));draw();Yield(1);}
static int load(void){int n=Read(package_path,bytes,sizeof(bytes));if(n<0){copy(status,"无法读取应用包。");return n;}int r=PackageValidate(package,(u32)n);if(r<0){copy(status,"包损坏、不兼容或包含未支持的权限。");return r;}copy(root,"/home/user/Programs/");copy(root+strlen(root),package->id);status[0]=0;return 0;}
static int repair(const char *id){if(!safe_id(id))return S_INVALID;AppRecord record;char path[128];copy(path,"/home/user/.sino/apps/");copy(path+strlen(path),id);copy(path+strlen(path),".rec");if(Read(path,&record,sizeof(record))!=(int)sizeof(record)||record.magic!=APP_RECORD_MAGIC)return S_NOTFOUND;copy(package_path,"/home/user/.sino/cache/");copy(package_path+strlen(package_path),id);copy(package_path+strlen(package_path),".sxp");if(load()<0)return S_INVALID;copy(root,record.root);optional=!!(record.manifest.components&2);page=3;return 0;}
static void edit(int key){char *s=field==1?package_path:field==2?root:0;if(!s)return;u32 n=strlen(s);if(key==8&&n)s[n-1]=0;else if(key>=32&&key<127&&n<100){s[n]=(char)key;s[n+1]=0;}else if(key==1)s[0]=0;}
int main(void){const char *args=Arguments();if(InstallRecover()<0){Log("INSTALL recovery failed or service busy\n");return 1;}if(streq(args,"/recover-only"))return 0;if(args[0]){if(args[0]=='/'&&args[1]=='q'&&args[2]=='u'&&args[3]=='i'&&args[4]=='e'&&args[5]=='t'&&args[6]==':'){quiet=1;copy(package_path,args+7);}else if(args[0]=='/'&&args[1]=='r'&&args[2]=='e'&&args[3]=='m'&&args[4]=='o'&&args[5]=='v'&&args[6]=='e'&&args[7]==':'){if(!safe_id(args+8))return 1;copy(operation,args+8);}else if(args[0]=='/'&&args[1]=='r'&&args[2]=='e'&&args[3]=='p'&&args[4]=='a'&&args[5]=='i'&&args[6]=='r'&&args[7]==':'){if(repair(args+8)<0)return 1;}else if(strlen(args)<128)copy(package_path,args);else return 1;}
 if(quiet){if(load()<0)return 1;result=InstallPackage(package,package_path,root,3,0);Log(result==0?"QUIET INSTALL PASS\n":"QUIET INSTALL FAIL\n");return result<0;}
 install_progress=progress;window=Window("SINO 原生软件安装程序",700,450);if(window<0)return 1;api(SYS_WINDOW_POLICY,(u32)window,1,0);draw();for(;;){UiEvent e;if(Event(&e)!=0){Yield(1);continue;}if(e.type==MSG_CLOSE){if(page!=4)break;continue;}if(e.type==MSG_KEY){if(e.key==27)break;edit(e.key);draw();continue;}if(ui_hit(&e,575,392,100,26))break;if(operation[0]){if(ui_hit(&e,414,392,120,26)){if(result==1)break;result=Uninstall(operation);Log(result==0?"SOFTWARE UNINSTALL PASS\n":"SOFTWARE UNINSTALL FAIL\n");copy(status,result==0?"卸载完成。":"卸载失败，已尝试回滚。");result=result==0?1:0;}draw();continue;}if(page==0&&ui_hit(&e,202,180,469,32))field=1;if(page==2&&ui_hit(&e,202,150,469,32))field=2;if(page==3&&(package->components&2)&&ui_hit(&e,205,165,350,26))optional=!optional;if(page>0&&page<4&&ui_hit(&e,335,392,100,26)){page--;status[0]=0;}if(ui_hit(&e,448,392,110,26)){field=0;if(page==5)break;if(page==0){if(load()==0)page=1;}else if(page<3)page++;else if(page==3){page=4;copy(status,"事务已开始；先保存回滚日志。");draw();Yield(1);result=InstallPackage(package,package_path,root,optional?3:1,0);Log(result==0?"SOFTWARE INSTALL PASS\n":"SOFTWARE INSTALL FAIL\n");copy(status,result==0?"文件、配置与快捷方式已提交。":"已回滚或保留恢复日志，请查看日志。");page=5;}}draw();}return 0;}
